const { test, expect } = await import(process.env.BW_PLAYWRIGHT_TEST);

const themeControl = (page) => page.getByRole("button", { name: /theme|dark|light/i });
const html = (page) => page.locator("html");

// A user activates the control with a click, or with Enter or Space while it has keyboard focus.
const ways = ["click", "Enter", "Space"];

async function activate(page, how) {
  if (how === "click") {
    await themeControl(page).click();
    return;
  }
  await themeControl(page).focus();
  await page.keyboard.press(how);
}

async function setTheme(page, how, want) {
  for (let i = 0; i < 3; i++) {
    if ((await html(page).getAttribute("data-theme")) === want) {
      break;
    }
    await activate(page, how);
  }
  await expect(html(page)).toHaveAttribute("data-theme", want);
}

const bodyBackground = (page) => page.locator("body").evaluate((el) => getComputedStyle(el).backgroundColor);

for (const how of ways) {
  test(`AC-018 The page shows a theme control. After it is activated once, the data-theme attribute of the html element is either light or dark. Each further activation changes the attribute to the other of those two values, and the computed background-color of the body element when data-theme is light differs from its computed background-color when data-theme is dark (${how})`, async ({ page }) => {
    await page.goto("index.html");
    await expect(themeControl(page)).toBeVisible();
    const background = {};
    let previous = null;
    for (let i = 0; i < 4; i++) {
      await activate(page, how);
      if (previous === null) {
        await expect(html(page)).toHaveAttribute("data-theme", /^(light|dark)$/);
      } else {
        await expect(html(page)).toHaveAttribute("data-theme", previous === "light" ? "dark" : "light");
      }
      const current = await html(page).getAttribute("data-theme");
      if (background[current] === undefined) {
        background[current] = await bodyBackground(page);
      } else {
        await expect(page.locator("body")).toHaveCSS("background-color", background[current]);
      }
      previous = current;
    }
    const other = previous === "light" ? "dark" : "light";
    await expect(page.locator("body")).not.toHaveCSS("background-color", background[other]);
  });
}

for (const how of ways) {
  for (const want of ["dark", "light"]) {
    const ac = want === "dark" ? "AC-019" : "AC-020";
    test(`${ac} After the theme control is used to set the html element's data-theme attribute to ${want} and the page is closed and reopened in the same browser profile, the html element has data-theme="${want}" before any user interaction with the reopened page (${how})`, async ({ page }) => {
      await page.goto("index.html");
      await setTheme(page, how, want);
      const context = page.context();
      await page.close();
      const reopened = await context.newPage();
      await reopened.goto("index.html");
      await expect(html(reopened)).toHaveAttribute("data-theme", want);
    });
  }
}

